"use client"

import { RadioGroup as RadioGroupPrimitive } from "@base-ui/react/radio-group"
import { Radio as RadioPrimitive } from "@base-ui/react/radio"

import { cn } from "@/lib/utils"

// Neon Vault RadioGroup: recessed dark rings; the selected item fills with the
// hero magenta material (gradient + sheen + rim + glow) shared with the
// primary Button, and the dot reads as a punched light.

function RadioGroup({ className, ...props }: RadioGroupPrimitive.Props) {
  return (
    <RadioGroupPrimitive data-slot="radio-group" className={cn("grid gap-2", className)} {...props} />
  )
}
RadioGroup.displayName = "RadioGroup"

function RadioGroupItem({ className, ...props }: RadioPrimitive.Root.Props) {
  return (
    <RadioPrimitive.Root
      data-slot="radio-group-item"
      className={cn(
        "inline-flex items-center justify-center aspect-square h-4.5 w-4.5 rounded-full border border-border bg-input",
        "[box-shadow:var(--shadow-inset)]",
        "transition-[background,box-shadow,border-color] duration-fast",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:ring-offset-2 focus-visible:ring-offset-background",
        "data-disabled:cursor-not-allowed data-disabled:opacity-50",
        "data-checked:border-transparent data-checked:bg-primary",
        "data-checked:[background-image:var(--gradient-primary)]",
        "data-checked:[box-shadow:var(--shadow-button)]",
        className
      )}
      {...props}
    >
      <RadioPrimitive.Indicator data-slot="radio-group-indicator" className="size-full flex items-center justify-center">
        <span className="h-2 w-2 rounded-full bg-primary-foreground [box-shadow:0_0.0625rem_0.125rem_oklch(0_0_0/0.35)]" />
      </RadioPrimitive.Indicator>
    </RadioPrimitive.Root>
  )
}
RadioGroupItem.displayName = "RadioGroupItem"

export { RadioGroup, RadioGroupItem }
